  static int? MouseInteger(IDictionary<string,object> map,string key,int min,int max){object value;return map!=null&&map.TryGetValue(key,out value)?MouseInteger(value,min,max):null;}
  static int? MouseArrayInteger(object[] array,int index,int min,int max){return array==null||index<0||index>=array.Length?null:MouseInteger(array[index],min,max);}
  MousePerformanceDraft MousePerformanceValues(Dictionary<string,object> state){
   string id=OriginalStateText(state,"deviceId","");var snapshot=GearOnline(state)?GearMap(state,"snapshot"):null;
   if(mousePerformanceDraft==null||mousePerformanceDraft.DeviceId!=id)mousePerformanceDraft=new MousePerformanceDraft{DeviceId=id};
   var draft=mousePerformanceDraft;var x=GearArray(snapshot,"dpiStages");var y=GearArray(snapshot,"dpiStagesY");
   for(int i=0;i<4;i++)if(!draft.DirtyDpi[i]){draft.DpiX[i]=MouseArrayInteger(x,i,100,65000);draft.DpiY[i]=MouseArrayInteger(y,i,100,65000);}
   int? stage=MouseInteger(snapshot,"activeDpiStage",1,4);if(!draft.DirtyStage)draft.SelectedStage=stage.HasValue?stage.Value-1:-1;
   if(!draft.DirtyPolling)draft.PollingRate=MouseInteger(snapshot,"pollingRate",125,8000);
