   if(!draft.DirtyMotion)draft.MotionSync=OriginalStateFlag(snapshot,"motionSync");
   return draft;
  }
  bool MouseCanEdit(Dictionary<string,object> state,string setting){return !closing&&!busy&&!mousePerformanceApplying&&GearCanSet(state,setting);}
  bool MouseHasDraftChanges(MousePerformanceDraft draft){return draft!=null&&(draft.DirtyDpi.Any(v=>v)||draft.DirtyStage||draft.DirtyPolling||draft.DirtyAngle||draft.DirtyMotion);}
  void RestoreMousePerformanceDraft(MousePerformanceDraft draft){
   mousePerformanceDraft=null;if(draft==null||draft.DeviceId==null||draft.DeviceId.Length>256||draft.DpiX==null||draft.DpiY==null||draft.DirtyDpi==null||draft.DpiX.Length!=4||draft.DpiY.Length!=4||draft.DirtyDpi.Length!=4||draft.SelectedStage< -1||draft.SelectedStage>3)return;
   for(int i=0;i<4;i++)if(draft.DpiX[i].HasValue&&(draft.DpiX[i]<100||draft.DpiX[i]>65000)||draft.DpiY[i].HasValue&&(draft.DpiY[i]<100||draft.DpiY[i]>65000)||draft.DirtyDpi[i]&&(!draft.DpiX[i].HasValue||draft.DpiY[i]!=draft.DpiX[i]))return;
   if(draft.PollingRate.HasValue&&!new[]{125,250,500,1000,2000,4000,8000}.Contains(draft.PollingRate.Value)||draft.DirtyPolling&&!draft.PollingRate.HasValue||draft.DirtyStage&&draft.SelectedStage<0||draft.DirtyAngle&&!draft.AngleSnapping.HasValue||draft.DirtyMotion&&!draft.MotionSync.HasValue)return;
   mousePerformanceDraft=draft;
  }
  bool MouseMayApply(Dictionary<string,object> state,MousePerformanceDraft draft){
   if(!HardwareWritesEnabled||busy||mousePerformanceApplying||draft==null||draft.DeviceId!=OriginalStateText(state,"deviceId","")||!MouseHasDraftChanges(draft))return false;
   return (!draft.DirtyDpi.Any(v=>v)||GearCanSet(state,"dpiStage"))&&(!draft.DirtyStage||GearCanSet(state,"activeDpiStage"))&&(!draft.DirtyPolling||GearCanSet(state,"pollingRate"))&&(!draft.DirtyAngle||GearCanSet(state,"angleSnapping"))&&(!draft.DirtyMotion||GearCanSet(state,"motionSync"));
  }
