  UIElement MouseTabStrip(Panel tabs,string[] names,string current){var shell=new Grid{Margin=new Thickness(-22,0,-22,0)};shell.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});shell.ColumnDefinitions.Add(new ColumnDefinition());shell.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var viewer=new ScrollViewer{Content=tabs,HorizontalScrollBarVisibility=ScrollBarVisibility.Hidden,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,CanContentScroll=false};Grid.SetColumn(viewer,1);shell.Children.Add(viewer);var previous=Button("‹",()=>viewer.ScrollToHorizontalOffset(Math.Max(0,viewer.HorizontalOffset-183)));var next=Button("›",()=>viewer.ScrollToHorizontalOffset(viewer.HorizontalOffset+183));foreach(var arrow in new[]{previous,next}){arrow.Width=18;arrow.Height=42;arrow.FontSize=20;arrow.Margin=new Thickness(0);arrow.Padding=new Thickness(0);arrow.BorderThickness=new Thickness(0);arrow.Background=Brushes.Transparent;}Grid.SetColumn(next,2);shell.Children.Add(previous);shell.Children.Add(next);bool aligned=false;viewer.ScrollChanged+=(s,e)=>{previous.Visibility=viewer.HorizontalOffset>0?Visibility.Visible:Visibility.Collapsed;next.Visibility=viewer.HorizontalOffset<viewer.ScrollableWidth?Visibility.Visible:Visibility.Collapsed;if(!aligned&&viewer.ViewportWidth>0&&viewer.ExtentWidth>0){aligned=true;int selected=Array.IndexOf(names,current);viewer.ScrollToHorizontalOffset(Math.Max(0,(selected+1)*183-viewer.ViewportWidth));}};return shell;}
  static List<KeyValuePair<string,object>> MousePerformanceCommands(MousePerformanceDraft draft,int? stageCount){
   if(draft==null||draft.DpiX==null||draft.DpiY==null||draft.DirtyDpi==null||draft.DpiX.Length!=4||draft.DpiY.Length!=4||draft.DirtyDpi.Length!=4)throw new ArgumentException("DPI 草稿格式无效。");int? rate=draft.PollingRate;bool? sync=draft.MotionSync;
   if(draft.DirtyDpi.Select((dirty,i)=>!dirty||draft.DpiX[i].HasValue&&draft.DpiY[i]==draft.DpiX[i]&&draft.DpiX[i]>=100&&draft.DpiX[i]<=65000).Any(valid=>!valid)||draft.DirtyPolling&&(!rate.HasValue||!new[]{125,250,500,1000,2000,4000,8000}.Contains(rate.Value))||draft.DirtyAngle&&!draft.AngleSnapping.HasValue||draft.DirtyMotion&&!sync.HasValue||draft.DirtyPolling&&rate==8000&&sync!=false||draft.DirtyMotion&&sync==true&&(!rate.HasValue||rate==8000)||draft.DirtyStage&&(!stageCount.HasValue||draft.SelectedStage<0||draft.SelectedStage>=stageCount.Value))throw new ArgumentException("当前草稿无法应用，请检查 DPI、轮询率与动态同步设置。");
   var commands=new List<KeyValuePair<string,object>>();if(draft.DirtyMotion&&sync==false)commands.Add(new KeyValuePair<string,object>("motionSync",false));if(draft.DirtyPolling)commands.Add(new KeyValuePair<string,object>("pollingRate",rate.Value));for(int i=0;i<4;i++)if(draft.DirtyDpi[i])commands.Add(new KeyValuePair<string,object>("dpiStage",new Dictionary<string,object>{{"index",i},{"dpi",draft.DpiX[i].Value}}));if(draft.DirtyAngle)commands.Add(new KeyValuePair<string,object>("angleSnapping",draft.AngleSnapping.Value));if(draft.DirtyMotion&&sync==true)commands.Add(new KeyValuePair<string,object>("motionSync",true));if(draft.DirtyStage)commands.Add(new KeyValuePair<string,object>("activeDpiStage",draft.SelectedStage+1));return commands;
  }
  async Task ApplyMousePerformanceDraftAsync(Dictionary<string,object> state,MousePerformanceDraft draft){
   if(!MouseMayApply(state,draft))return;List<KeyValuePair<string,object>> commands;try{commands=MousePerformanceCommands(draft,MouseInteger(GearMap(state,"snapshot"),"dpiStageCount",1,4));}catch(ArgumentException error){Log(error.Message);return;}
   mousePerformanceApplying=true;try{ShowPage(page);foreach(var command in commands){Dictionary<string,object> current;if(!gearStates.TryGetValue("mouse",out current)||!GearOnline(current)||OriginalStateText(current,"deviceId","")!=draft.DeviceId||!CanApplyGear(current,command.Key))break;await SetGearSetting("mouse",current,command.Key,command.Value);Dictionary<string,object> after;if(!gearStates.TryGetValue("mouse",out after)||Object.ReferenceEquals(current,after)||OriginalStateFlag(after,"writeConfirmed")!=true)break;if(command.Key=="dpiStage")draft.DirtyDpi[Convert.ToInt32(((Dictionary<string,object>)command.Value)["index"],CultureInfo.InvariantCulture)]=false;else if(command.Key=="pollingRate")draft.DirtyPolling=false;else if(command.Key=="angleSnapping")draft.DirtyAngle=false;else if(command.Key=="motionSync")draft.DirtyMotion=false;else if(command.Key=="activeDpiStage")draft.DirtyStage=false;}}finally{mousePerformanceApplying=false;if(!closing)ShowPage(page);}
  }
